import assert from "node:assert/strict";
import { test } from "node:test";
import { parseCsv } from "../src/csv.js";

test("CSV import defaults currency when the optional meta column is absent", () => {
	const rows = parseCsv("date;payee;amount;memo\n2026-10-19;Fresh Market;29.66;Groceries");
	assert.equal(rows.length, 1);
	assert.equal(rows[0].currency, "EUR");
	assert.equal(rows[0].payee, "Fresh Market");
});

test("CSV import defaults currency when the meta cell is missing or empty", () => {
	for (const suffix of ["", ";"]) {
		const rows = parseCsv(`date;payee;amount;memo;meta\n2026-10-19;Fresh Market;29.66;Groceries${suffix}`);
		assert.equal(rows[0].currency, "EUR");
	}
});

test("CSV import preserves explicit currency and defaults missing currency", () => {
	for (const [meta, expected] of [[ '{"currency":"USD"}', "USD" ], ["{}", "EUR"], ["null", "EUR"]]) {
		const rows = parseCsv(`date;payee;amount;memo;meta\n2026-10-19;Fresh Market;29.66;Groceries;${meta}`);
		assert.equal(rows[0].currency, expected);
	}
});

