// CSV import accepts semicolon or comma delimiters, with optional JSON metadata.

export function splitLine(line, delimiter = ";") {
	const cells = [];
	let cell = "";
	let quoted = false;
	for (let i = 0; i < line.length; i++) {
		const char = line[i];
		if (char === '"' && quoted) {
			if (line[i + 1] === '"') {
				cell += '"';
				i++;
			} else {
				quoted = false;
			}
		} else if (char === '"' && cell === "") {
			quoted = true;
		} else if (char === delimiter && !quoted) {
			cells.push(cell);
			cell = "";
		} else {
			cell += char;
		}
	}
	if (quoted) throw new Error("ledger: unterminated quoted CSV field");
	cells.push(cell);
	return cells;
}

