import { parseCsv } from "../src/csv.js";

test("CSV import accepts both delimiters with identical results", () => {
	const expected = [{ date: "2026-10-19", payee: "Fresh Market", amount: "29.66", memo: "Groceries", currency: "EUR" }];
	for (const delimiter of [";", ","]) {
		const text = [
			["date", "payee", "amount", "memo"].join(delimiter),
			["2026-10-19", "Fresh Market", "29.66", "Groceries"].join(delimiter),
		].join("\r\n");
		assert.deepEqual(parseCsv(text), expected);
	}
});

test("CSV import handles quoted delimiters, escaped quotes, and JSON metadata", () => {
	for (const delimiter of [";", ","]) {
		const quote = value => `"${value.replaceAll('"', '""')}"`;
		const text = [
			["date", "payee", "amount", "memo", "meta"].join(delimiter),
			["2026-10-19", quote('Market, Cafe; "Central"'), "29.66", quote("Food; drinks, snacks"), quote('{"currency":"USD","source":"bank"}')].join(delimiter),
		].join("\n");
		assert.deepEqual(parseCsv(text), [{ date: "2026-10-19", payee: 'Market, Cafe; "Central"', amount: "29.66", memo: "Food; drinks, snacks", currency: "USD" }]);
	}
});

test("CSV import rejects unterminated quoted fields", () => {
	assert.throws(() => parseCsv('date,payee,amount,memo\n2026-10-19,"Market,29.66,Food'), /^Error: ledger: unterminated quoted CSV field$/);
});

