import assert from "node:assert/strict";
import { test } from "node:test";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

function report(t, args, transactions = []) {
	const home = mkdtempSync(join(tmpdir(), "ledger-test-"));
	t.after(() => rmSync(home, { recursive: true, force: true }));
	writeFileSync(join(home, "transactions.json"), JSON.stringify(transactions));
	return spawnSync(process.execPath, ["src/cli.js", "report", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
}

test("report --since filters inclusively and uses LEDGER_HOME", t => {
	const result = report(t, ["--since", "2026-02-28"], [
		{ date: "2026-02-27", category: "food", amount_cents: -900 },
		{ date: "2026-02-28", category: "Food", amount_cents: -100 },
		{ date: "2026-03-01", category: "food", amount_cents: -250 },
		{ date: "2026-03-02", category: "food", amount_cents: 50 },
		{ date: "2026-03-01", category: "__proto__", amount_cents: -400 },
	]);
	assert.equal(result.status, 0);
	assert.equal(result.stderr, "");
	assert.equal(result.stdout, "__proto__: 400 cents\nfood: 300 cents\n");
});

test("report rejects invalid dates and arguments", t => {
	for (const args of [
		["--since"], ["--since", "2026-02-29"], ["--since", "2026-04-31"],
		["--since", "2026-13-01"], ["--since", "2026-00-01"],
		["--since", "2026-01-00"], ["--since", "2026-1-01"],
		["--since", "garbage"], ["--since", "2026-01-01\n"],
		["--since", "2026-01-01", "extra"], ["--unknown"],
	]) {
		const result = report(t, args);
		assert.equal(result.status, 1, JSON.stringify(args));
		assert.match(result.stderr, /^ledger: /);
		assert.equal(result.stdout, "");
	}
});

test("report accepts a leap day in a leap year", t => {
	assert.equal(report(t, ["--since", "2024-02-29"]).status, 0);
});

test("report defaults to the current calendar month", t => {
	const now = new Date();
	const month = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
	const result = report(t, [], [
		{ date: `${month}-01`, category: "food", amount_cents: -123 },
		{ date: "1900-01-01", category: "food", amount_cents: -999 },
	]);
	assert.equal(result.status, 0);
	assert.equal(result.stdout, "food: 123 cents\n");
});

