import assert from "node:assert/strict";
import { test } from "node:test";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { spawnSync } from "node:child_process";

function balance(t, transactions, args = []) {
	const home = mkdtempSync(join(tmpdir(), "ledger-balance-test-"));
	t.after(() => rmSync(home, { recursive: true, force: true }));
	if (transactions !== undefined) writeFileSync(join(home, "transactions.json"), JSON.stringify(transactions));
	return spawnSync(process.execPath, ["src/cli.js", "balance", ...args], {
		env: { ...process.env, LEDGER_HOME: home }, encoding: "utf8",
	});
}

test("balance sums accounts, sorts names, and formats integer cents", t => {
	const result = balance(t, [
		{ account: "Savings", amount_cents: 123456 },
		{ account: "Credit Card", amount_cents: -100 },
		{ account: "Checking", amount_cents: 1000 },
		{ account: "Checking", amount_cents: -1000 },
		{ account: "Credit Card", amount_cents: 93 },
		{ account: "__proto__", amount_cents: 1 },
		{ account: "checking", amount_cents: 200 },
	]);
	assert.equal(result.status, 0);
	assert.equal(result.stderr, "");
	assert.equal(result.stdout, "Checking: 0.00\nCredit Card: -0.07\nSavings: 1234.56\n__proto__: 0.01\nchecking: 2.00\n");
});

test("balance preserves exact sums beyond the safe number range", t => {
	const result = balance(t, [
		{ account: "Savings", amount_cents: Number.MAX_SAFE_INTEGER },
		{ account: "Savings", amount_cents: Number.MAX_SAFE_INTEGER },
	]);
	assert.equal(result.status, 0);
	assert.equal(result.stdout, "Savings: 180143985094819.82\n");
});

test("balance handles empty data", t => {
	const result = balance(t, []);
	assert.equal(result.status, 0);
	assert.equal(result.stdout, "");
});

test("balance rejects missing or invalid transaction data", t => {
	for (const data of [undefined, {}, [null], [{}],
		[{ account: "", amount_cents: 1 }],
		[{ account: "Checking", amount_cents: "100" }],
		[{ account: "Checking", amount_cents: 1.5 }],
		[{ account: "Checking", amount_cents: Number.MAX_SAFE_INTEGER + 1 }],
	]) {
		const result = balance(t, data);
		assert.equal(result.status, 2);
		assert.equal(result.stderr, "ledger: cannot read transaction data\n");
		assert.equal(result.stdout, "");
	}
});

test("balance rejects arguments", t => {
	const result = balance(t, [], ["extra"]);
	assert.equal(result.status, 1);
	assert.equal(result.stderr, "ledger: usage: balance\n");
});
